  background: radial-gradient(circle at 8% 0%, oklch(95% 0.06 265), transparent 30rem), var(--surface);
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; }
img, svg { max-width: 100%; }
.container { width: min(1160px, calc(100% - 40px)); margin: 0 auto; }
.nav {
