.preview-panel { display: none; animation: rise .35s ease both; }
.preview-panel.active { display: block; }
.metric-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 18px; }
.mini-metric { padding: 14px; border-radius: 18px; background: var(--primary-soft); }
.mini-metric strong { display: block; font-size: 1.4rem; }
.chart { height: 156px; border-radius: 22px; background: linear-gradient(180deg, oklch(52% 0.24 265 / .18), transparent), repeating-linear-gradient(90deg, transparent, transparent 34px, var(--line) 35px); position: relative; overflow: hidden; }
