.course-preview { display: grid; gap: 12px; }
.lesson { display: flex; gap: 12px; align-items: center; padding: 14px; border: 1px solid var(--line); border-radius: 18px; }
.lesson-icon { width: 42px; height: 42px; border-radius: 14px; background: linear-gradient(135deg, var(--primary), var(--lime)); }
.stats-bar { padding: 22px 0 70px; }
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; background: var(--ink); color: white; padding: 22px; border-radius: 30px; box-shadow: var(--shadow); }
.stat { padding: 22px; border-radius: 22px; background: oklch(100% 0 0 / .07); }
.stat strong { display: block; font-size: clamp(2rem, 5vw, 4.2rem); letter-spacing: -.06em; line-height: 1; }
.stat span { color: oklch(89% 0.02 265); font-weight: 800; }
.section { padding: 78px 0; }
.section.alt { background: linear-gradient(180deg, var(--surface-2), white); }
.section-head { display: flex; justify-content: space-between; align-items: end; gap: 28px; margin-bottom: 34px; }
.section-head p { max-width: 560px; color: var(--muted); margin: 0; font-size: 1.08rem; }
.grid { display: grid; gap: 20px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.card { background: white; border: 1px solid var(--line); border-radius: 26px; padding: 26px; box-shadow: var(--shadow-soft); transition: transform .22s ease, box-shadow .22s ease; }
