.card p { color: var(--muted); margin-bottom: 0; }
.icon { width: 52px; height: 52px; border-radius: 18px; display: grid; place-items: center; margin-bottom: 18px; background: var(--primary-soft); color: var(--primary); font-weight: 950; }
.icon.accent { background: oklch(95% 0.035 26); color: var(--accent); }
.tabs-layout { display: grid; grid-template-columns: .8fr 1.2fr; gap: 26px; align-items: start; }
.feature-tabs { display: grid; gap: 10px; }
.feature-tab { text-align: left; border-radius: 18px; border: 1px solid var(--line); background: white; padding: 16px; }
