.logo-tile:before { content: ''; width: 30px; height: 30px; border-radius: 10px; background: linear-gradient(135deg, var(--primary), var(--accent)); display: block; margin-bottom: 6px; justify-self: center; }
.carousel { position: relative; }
.carousel-track { overflow: hidden; }
.testimonial { display: none; }
.testimonial.active { display: grid; animation: rise .35s ease both; }
.quote { font-size: clamp(1.45rem, 3vw, 2.4rem); letter-spacing: -.04em; line-height: 1.14; font-weight: 900; }
.carousel-controls { display: flex; gap: 10px; margin-top: 22px; }
.round-btn { width: 46px; height: 46px; border-radius: 50%; border: 1px solid var(--line); background: white; cursor: pointer; font-size: 1.2rem; }
.pricing-card { position: relative; overflow: hidden; }
.price { font-size: 3rem; font-weight: 950; letter-spacing: -.06em; }
.badge { display: inline-flex; border-radius: 999px; padding: 7px 10px; background: var(--lime); font-weight: 950; font-size: .78rem; }
