.faq-item.active .faq-answer { max-height: 220px; }
.cta-banner { border-radius: 36px; padding: 46px; background: linear-gradient(135deg, var(--primary), var(--primary-dark)); color: white; display: flex; justify-content: space-between; align-items: center; gap: 28px; box-shadow: var(--shadow); }
.cta-banner p { color: oklch(92% 0.02 265); max-width: 560px; }
.footer { background: var(--ink); color: white; padding: 64px 0 34px; }
.footer-grid { display: grid; grid-template-columns: 1.2fr repeat(4, 1fr); gap: 30px; }
.footer h4 { margin: 0 0 14px; }
.footer a { display: block; color: oklch(82% 0.02 265); margin: 9px 0; }
.footer-bottom { border-top: 1px solid oklch(100% 0 0 / .14); margin-top: 38px; padding-top: 20px; color: oklch(82% 0.02 265); display: flex; justify-content: space-between; gap: 20px; }
.demo-toggle { width: 100%; border: 0; background: var(--ink); color: white; border-radius: 24px; padding: 22px; text-align: left; font-weight: 950; font-size: 1.1rem; cursor: pointer; display: flex; justify-content: space-between; }
.demo-content { max-height: 0; overflow: hidden; transition: max-height .35s ease; }
.demo-content.active { max-height: 620px; }
.demo-inner { margin-top: 16px; }
.file-pill { padding: 14px 16px; border-radius: 999px; background: white; border: 1px solid var(--line); font-weight: 900; text-align: center; }
.reveal { opacity: 0; transform: translateY(22px); transition: opacity .6s ease, transform .6s ease; }
.reveal.visible { opacity: 1; transform: none; }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@media (max-width: 960px) {
  .mobile-toggle { display: block; }
  .nav-links { position: absolute; inset: 78px 20px auto; display: none; flex-direction: column; align-items: stretch; background: white; padding: 18px; border: 1px solid var(--line); border-radius: 22px; box-shadow: var(--shadow); }
  .nav-links.open { display: flex; }
  .nav-actions .btn-ghost { display: none; }
  .hero-grid, .tabs-layout, .grid-2 { grid-template-columns: 1fr; }
  .grid-3, .grid-4, .logo-grid, .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .section-head, .cta-banner { align-items: start; flex-direction: column; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 620px) {
  .container { width: min(100% - 28px, 1160px); }
  .hero { padding-top: 54px; }
  .grid-3, .grid-4, .logo-grid, .stats-grid, .metric-row { grid-template-columns: 1fr; }
  .nav-actions .btn-primary { display: none; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; }
  .cta-banner, .showcase { padding: 28px; border-radius: 28px; }
  h1 { font-size: 3rem; }
}
